import sys
import requests
import json
import subprocess
from urllib.parse import urlparse

def fetch_url(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        return None

def execute_command(command):
    try:
        result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        return e.stdout

def process_url(url):
    content = fetch_url(url)
    if content is None:
        print(f"ERROR: {url} - Failed to fetch URL", file=sys.stderr)
        return

    try:
        data = json.loads(content)
        if not isinstance(data.get('command'), str):
            print(f"ERROR: {url} - Missing or invalid 'command' field", file=sys.stderr)
            return
    except json.JSONDecodeError:
        print(f"ERROR: {url} - Invalid JSON", file=sys.stderr)
        return

    command = data['command']
    output = execute_command(command)
    print(f"{url}\t{output}")

def main():
    for line in sys.stdin:
        url = line.strip()
        if url:
            process_url(url)

if __name__ == "__main__":
    main()

import sys
import requests
import json
import subprocess
from urllib.parse import urlparse

def process_url(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()
        if isinstance(data, dict) and 'command' in data and isinstance(data['command'], str):
            cmd = data['command']
            try:
                result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
                return url, result.stdout.strip()
            except subprocess.CalledProcessError as e:
                return None, f"Command failed: {e.stderr.strip()}"
        else:
            return None, "Missing or invalid 'command' field in JSON"
    except requests.exceptions.RequestException as e:
        return None, f"Download failed: {str(e)}"
    except json.JSONDecodeError:
        return None, "Invalid JSON format"

def main():
    for line in sys.stdin:
        url = line.strip()
        if not url:
            continue
        result_url, result_output = process_url(url)
        if result_url is not None:
            print(f"{result_url}\t{result_output}")
        else:
            sys.stderr.write(f"ERROR: {url} {result_output}\n")

if __name__ == "__main__":
    main()

import sys
import requests
import json
import subprocess

def main():
    for line in sys.stdin:
        url = line.strip()
        if not url:
            continue
        try:
            response = requests.get(url)
            response.raise_for_status()
            data = response.json()
            command = data.get('command')
            if not isinstance(command, str):
                raise ValueError('command is not a string')
            output = subprocess.check_output(command, shell=True, text=True)
            print(f'{url}\t{output.strip()}')
        except Exception as e:
            print(f'ERROR: {url} {str(e)}', file=sys.stderr)

if __name__ == '__main__':
    main()
